# Until now every member and every new national officer was enrolled in
# settings.ED_COURSES; carry those courses over so nothing changes on deploy.
def seed_from_ed_courses(apps, schema_editor):
    from core.models import NAT_OFFICERS

    EdCourse = apps.get_model("trainings", "EdCourse")
    for course_id in getattr(settings, "ED_COURSES", None) or []:
        course_id = course_id.strip()
        if course_id:
            EdCourse.objects.get_or_create(
                course_id=course_id,
                defaults={
                    "title": course_id,
                    "assign_to_all_members": True,
                    "assign_to_roles": list(NAT_OFFICERS),
                },
            )


